"""Scratch A/B of call-scoped immutable import syntax keyed by fresh source bytes."""
import ast
from collections import OrderedDict
import hashlib
import json
from pathlib import Path
import statistics
import sys
import time

REPO=Path('/Users/jakefitzgerald/.codex/worktrees/3c6b/text-to-cad')
sys.path.insert(0,str(REPO/'scripts/bench/cadgen-performance'))
from common import metadata,source_fingerprint
from cadgen.store import closure as cl


def syntax(payload, filename):
    nodes=tuple(ast.walk(ast.parse(payload,filename=filename)))
    imports=[]
    wanted=set()
    for node in nodes:
        if isinstance(node,ast.Import):
            names=tuple((alias.name,alias.asname or '') for alias in node.names)
            imports.append((0,'',0,names))
            wanted.update(alias or name.split('.')[0] for name,alias in names)
        elif isinstance(node,ast.ImportFrom):
            names=tuple((alias.name,alias.asname or '') for alias in node.names)
            imports.append((1,node.module or '',node.level,names))
            wanted.update(alias or name for name,alias in names)
    attributes={id(node.value):node.attr for node in nodes if isinstance(node,ast.Attribute) and isinstance(node.ctx,ast.Load) and isinstance(node.value,ast.Name) and node.value.id in wanted}
    takes={name:set() for name in wanted}
    for node in nodes:
        if isinstance(node,ast.Name) and isinstance(node.ctx,ast.Load) and node.id in wanted:
            if id(node) not in attributes:
                takes[node.id]=None
            elif takes[node.id] is not None:
                takes[node.id].add(attributes[id(node)])
    return tuple(imports),tuple(sorted((name,None if values is None else tuple(sorted(values))) for name,values in takes.items()))


memo=OrderedDict()
size=0
counts={}


def candidate(script):
    global size
    script=Path(script).resolve()
    try:
        payload=script.read_bytes()
        cached=memo.get(payload)
        if cached is None:
            recipe=syntax(payload,str(script))
            counts['misses']+=1
            if len(payload)<=65536 and len(memo)<256:
                memo[payload]=recipe
                size+=len(payload)
        else:
            counts['hits']+=1
            recipe=cached
    except (OSError,SyntaxError,ValueError):
        return cl.StaticImports((),())
    roots=cl._search_roots(script)
    sources=[]; children=[]; constants={}; imports={}
    taken_lookup=dict(recipe[1])
    def taken(name):
        values=taken_lookup[name]
        return None if values is None else set(values)
    def note(target,names):
        if target==script or not cl.is_first_party_source_file(target):
            return
        previous=imports.get(target,set())
        imports[target]=None if names is None or previous is None else previous|names
    for kind,module,level,names in recipe[0]:
        if kind==0:
            for name,alias in names:
                target=cl._resolve_module(name,roots)
                if target is not None:
                    note(target,taken(alias or name.split('.')[0]))
            continue
        if level:
            base=script.parent
            for _ in range(level-1):
                base=base.parent
            from_roots=[base]
        else:
            from_roots=roots
        prefix=f'{module}.' if module else ''
        target=cl._resolve_module(module,from_roots) if module else None
        remaining={name for name,_ in names}
        if '*' in remaining:
            if target is not None:
                note(target,None)
            continue
        for name,alias in names:
            sub_target=cl._resolve_module(prefix+name,from_roots)
            if sub_target is not None:
                note(sub_target,taken(alias or name))
                remaining.discard(name)
        if remaining and target is not None:
            note(target,remaining)
    for target,names in imports.items():
        model_names=cl._model_function_names(str(target))
        if not model_names or names is None:
            sources.append(target)
            continue
        beyond=names-model_names
        literals=(cl.module_constant_hashes(target,beyond) or {}) if beyond else {}
        if set(literals)==beyond:
            children.append(target)
            if literals:
                constants.setdefault(str(target),{}).update(literals)
        else:
            sources.append(target)
    return cl.StaticImports(tuple(sources),tuple(children),constants)


def main():
    global size
    initial=metadata()
    root=REPO/'models/tmp/split-stage-profile-20260910/src'
    script=root/'planetary_gear_assembly.py'
    children=[path for path in root.glob('*.py') if path!=script]
    executed={str(path.resolve()):cl._semantic_source_hash(path) for path in root.rglob('*.py')}
    original=cl.static_imports
    rows=[]
    expected=cl.build_closure(script,executed=executed,children=children)
    try:
        for sample in range(5):
            for mode in (['existing','syntax-recipe'] if sample%2==0 else ['syntax-recipe','existing']):
                memo.clear();size=0;counts.clear();counts.update(hits=0,misses=0)
                cl.static_imports=original if mode=='existing' else candidate
                started=time.perf_counter()
                got=cl.build_closure(script,executed=executed,children=children)
                elapsed=(time.perf_counter()-started)*1000
                assert got==expected
                rows.append({'sample':sample,'mode':mode,'milliseconds':elapsed,'cache':dict(counts),'sourceBytesRetained':size,'entries':len(memo)})
    finally:
        cl.static_imports=original
    medians={mode:statistics.median(row['milliseconds'] for row in rows if row['sample'] and row['mode']==mode) for mode in ['existing','syntax-recipe']}
    report={'metadata':initial,'helperSource':Path(__file__).read_text(encoding='utf-8'),'helperSha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'qualification':'Four interleaved warm samples of a full real nine-child build_closure after one unreported-in-median priming sample. Every candidate call gets a new syntax memo and every lookup reads source bytes and resolves current filesystem availability. Scratch admission is conservatively limited to256files of <=64KiB; production would charge actual retained recipes and input bytes. No kernel work/model build/STEP persistence.', 'rows':rows,'medianMs':medians,'relativeChangePercent':(medians['syntax-recipe']/medians['existing']-1)*100,'allClosureValuesExactlyEqual':True,'inputSourceSha256':{str(path.relative_to(root)):hashlib.sha256(path.read_bytes()).hexdigest() for path in root.rglob('*.py')},'runtimeUnchanged':source_fingerprint()==initial['sourceFingerprint']}
    assert report['runtimeUnchanged']
    out=REPO/'scripts/bench/cadgen-performance/results/closure-syntax-probe-20260910.json'
    assert not out.exists()
    out.write_text(json.dumps(report,indent=2,sort_keys=True)+'\n',encoding='utf-8')
    print(json.dumps({'medianMs':medians,'relativeChangePercent':report['relativeChangePercent'],'rows':rows},indent=2))


if __name__=='__main__':
    main()
